changeSet.sql:
CREATE TABLE model_calibrations ( id BIGSERIAL PRIMARY KEY, model_name TEXT NOT NULL, calibration_key_hash TEXT, calibration_key JSONB, profile JSONB NOT NULL, source_provider_id INTEGER REFERENCES providers(id) ON DELETE SET NULL, calibrated_at TIMESTAMPTZ NOT NULL, confirmations INTEGER NOT NULL DEFAULT 0, divergences INTEGER NOT NULL DEFAULT 0, invalidated_at TIMESTAMPTZ, invalidation_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE INDEX idx_model_calibrations_lookup ON model_calibrations (model_name, calibration_key_hash, calibrated_at DESC) WHERE invalidated_at IS NULL;
-- Leads with the FK column so a provider delete is index-backed. CREATE UNIQUE INDEX uq_model_calibrations_source_run ON model_calibrations (source_provider_id, model_name, calibrated_at);

rollback.sql:
DROP INDEX IF EXISTS idx_model_profiles_calibration;
ALTER TABLE model_profiles
    DROP COLUMN IF EXISTS sync_revision,
    DROP COLUMN IF EXISTS calibration_key_hash,
    DROP COLUMN IF EXISTS calibration_id,
    DROP COLUMN IF EXISTS profile;

changeSet.sql:
DROP INDEX IF EXISTS idx_model_profiles_provider;
DROP INDEX IF EXISTS idx_model_profiles_model_name;
DROP INDEX IF EXISTS idx_model_profiles_source;

rollback.sql:
CREATE INDEX IF NOT EXISTS idx_model_profiles_provider
    ON model_profiles (provider_id);
CREATE INDEX IF NOT EXISTS idx_model_profiles_model_name
    ON model_profiles (model_name);
CREATE INDEX IF NOT EXISTS idx_model_profiles_source
    ON model_profiles (residency_source)
    WHERE residency_source != 'measured';
